using System.IO;
using System.Threading;
using System.Threading.Tasks;

namespace Comment.Application.Providers.Storage;

public sealed record CommentMediaObjectWriteResult(
    string PrivateObjectReference,
    string ObjectVersion);

/// <summary>
/// Exact-object storage port for the durable media workflow. All keys are
/// generated by the domain/application and implementations must treat delete as
/// idempotent. Quarantine objects are never returned to an API response.
/// </summary>
public interface ICommentMediaObjectStore
{
    Task<CommentMediaObjectWriteResult> PutQuarantineAsync(
        int ownerUserId,
        string objectName,
        string contentType,
        Stream content,
        CancellationToken cancellationToken);

    Task<bool> QuarantineExistsAsync(
        int ownerUserId,
        string objectName,
        CancellationToken cancellationToken);

    Task<Stream> OpenQuarantineReadAsync(
        int ownerUserId,
        string objectName,
        CancellationToken cancellationToken);

    Task<Stream> OpenFinalReadAsync(
        int ownerUserId,
        string objectName,
        CancellationToken cancellationToken);

    Task<CommentMediaObjectWriteResult> PromoteAsync(
        int ownerUserId,
        string quarantineObjectName,
        string finalObjectName,
        string contentType,
        long sizeBytes,
        CancellationToken cancellationToken);

    Task DeleteQuarantineAsync(
        int ownerUserId,
        string objectName,
        CancellationToken cancellationToken);

    Task DeleteFinalAsync(
        int ownerUserId,
        string objectName,
        CancellationToken cancellationToken);
}
